import {
  Group,
  Mesh,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Vector2,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Plane (sprite) with texture from atlas region ---
  const srcRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = srcRect.w / srcRect.h; // ~1.6
  const geometry = new PlaneGeometry(1.6, 1); // width = 1.6, height = 1 (maintains aspect)

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Load texture and apply atlas offset/repeat
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    const img = tex.image;
    if (img) {
      const tw = img.width;
      const th = img.height;
      // Compute repeat to isolate the atlas region
      const repeatU = srcRect.w / tw;
      const repeatV = srcRect.h / th;
      tex.repeat.set(repeatU, repeatV);
      tex.offset.set(srcRect.x / tw, srcRect.y / th);
    } else {
      // Fallback: assume texture is exactly the region
      tex.repeat.set(1, 1);
      tex.offset.set(0, 0);
    }
    tex.needsUpdate = true;
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text: "Features 3" ---
  const textMesh = ctx.fontAtlas.createText('Features 3', {
    fontSize: 39,
    color: '#e8ecf2', // paper
    align: 'center',
    maxWidthPx: 190, // roughly fits width of card
  });
  // Position text slightly in front of plane
  if (textMesh) {
    textMesh.position.set(0, 0, 0.005);
    // Scale if needed (text is in screen pixels, convert to scene units using fontAtlas default scaling)
    // Typical: fontSize in pixels translates to scene units ~ fontSize/72? We'll keep default.
    group.add(textMesh);
  }

  // --- Scene placement ---
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // --- Cleanup ---
  const geometryRef = geometry;
  const materialRef = material;
  group.userData.cleanup = () => {
    geometryRef.dispose();
    materialRef.dispose();
    // Clean up timeline if any (none here)
  };

  // No event handlers needed
  group.userData.handlers = {};

  return group;
}
